const TESTS = ["adhd", "anxiety", "atst", "autism", "big5-test", "big5", "bpd", "bt", "career", "depression", "et", "fa", "iq", "ll", "ls", "ma", "narcissist", "ndt", "nd", "occ", "ocd", "ps", "sf", "so", "love_language", "love_styles", "attachment_style", "iq-test", "empath", "bipolar"];
const nm = k => typeof k.key_name === 'object' ? (k.key_name.web || k.key_name.other) : k.key_name;
const alt = TESTS.map(t => t.replace(/[-]/g, '\\-')).sort((a,b) => b.length - a.length).join('|');
const RE = new RegExp('(^|_|::)(' + alt + ')(?=$|_|::)');
const EXCL = /components::members::profile|terms_and_conditions|privacy_policy|cookie|legal|_questions\./;
const fam = {}; const all = [];
for (const it of $input.all()) { if (!Array.isArray(it.json.keys)) throw new Error('no keys'); for (const k of it.json.keys) all.push([k.key_id, nm(k) || '']); }
const names = new Set(all.map(x => x[1]));
for (const [id, n] of all) { if (EXCL.test(n)) continue; const m = n.match(RE); let sig = null, t = null;
  if (m) { sig = n.replace(RE, (s, a) => a + '{T}'); t = m[2]; } else { sig = n + '_{T}'; t = '(base)'; }
  (fam[sig] = fam[sig] || []).push({ id, n, t }); }
const keep = {}; for (const [sig, arr] of Object.entries(fam)) { const tests = new Set(arr.filter(x => x.t !== '(base)').map(x => x.t)); if (tests.size >= 3) keep[sig] = arr; }
const ids = []; const fmap = {}; for (const [sig, arr] of Object.entries(keep)) for (const x of arr) { ids.push(x.id); fmap[x.id] = [sig, x.t]; }
const out = []; for (let i = 0; i < ids.length; i += 100) out.push({ json: { n: ids.length, nf: Object.keys(keep).length, url: 'https://api.lokalise.com/api2/projects/31393214664f295f94dd86.76792605/keys?limit=100&include_translations=1&disable_references=1&filter_translation_lang_ids=640,767,666,1056,10154,673,757,734,733,10152,10153,749,737,760,748,708,770,754,753&filter_key_ids=' + ids.slice(i, i+100).join(',') } });
out[0].json.fmap = fmap; return out;

const LING = ["47natcha@gmail.com", "arandatrad@gmail.com", "austra.muizniece@gmail.com", "boh.vozniuk@gmail.com", "bruno@bsttranslations.com", "daniel@dgmultilingualservices.com", "dmluciahorea@gmail.com", "ellen.de.venter@outlook.com", "farahputri@gmail.com", "futuremedia@sdl.com", "harald.roald@gmail.com", "ilaria.roncaglia@gmail.com", "ivanaturcin@ymail.com", "jaromirvicari@me.com", "julius.valkiunas@gmail.com", "karahansisman@gmail.com", "katri.varvikko@gmail.com", "kenneth@phraseit.dk", "marit.teichmann@gmail.com", "michal.tosza@translators.org.pl", "mjlocalize@gmail.com", "mteixeira@sacradomus.com", "mteres@terestraducciones.com", "nerissaneptuno@gmail.com", "qrcodelocalization@gmail.com", "quentinnguyen.localize@gmail.com", "root-translations@outlook.com", "roxanamoldovan25@gmail.com", "ruckova.lucia@gmail.com", "sabrathan@gmail.com", "sara.guinot.trad@gmail.com", "silis.martins@gmail.com", "silke.luehrmann@gmx.de", "straus.translations@gmail.com", "therese.svardsten@gmail.com", "translation@cornell.hu", "vidiasc@gmail.com"];
const LANGS = $('Langs').first().json.langs; const fmap = $('Pick').first().json.fmap;
const NAMES = { es:'Spanish (Spain)', fr:'French (France)', it:'Italian', pt:'Portuguese (Brazil)', ro:'Romanian', pl:'Polish', lt:'Lithuanian', lv:'Latvian', de:'German', nl:'Dutch', da:'Danish', sv:'Swedish', no:'Norwegian Bokm\u00e5l', et:'Estonian', ms:'Malay', id:'Indonesian', ko:'Korean', th:'Thai' };
const all = []; for (const it of $input.all()) { if (!Array.isArray(it.json.keys)) throw new Error('no keys'); all.push(...it.json.keys); }
const nm = k => typeof k.key_name === 'object' ? (k.key_name.web || k.key_name.other) : k.key_name;
const out = [];
for (const iso of LANGS) {
  const fams = {};
  for (const k of all) { const f = fmap[k.key_id]; if (!f) continue; const en = (k.translations||[]).find(t => t.language_iso === 'en'); const tr = (k.translations||[]).find(t => t.language_iso === iso);
    if (!tr || typeof tr.translation !== 'string' || !tr.translation) continue;
    (fams[f[0]] = fams[f[0]] || []).push({ i: tr.translation_id, kid: k.key_id, key: nm(k), test: f[1], en: en ? en.translation : '', t: tr.translation, lock: LING.includes(tr.modified_by_email) }); }
  let batch = []; let cnt = 0;
  const flush = () => { if (!batch.length) return;
    const sys = 'You are a senior native ' + NAMES[iso] + ' copywriter and localizer for Personality.co. You receive GROUPS of sibling UI strings: the same UI element repeated for different tests (key names differ only by the test code, shown as "test"). In every group at least one member has "lock": true \u2014 it was written by our professional linguist and is the REFERENCE. TASK: rewrite every non-locked member so it copies the linguist\'s reference wording, sentence structure, verb choice, register, punctuation and capitalization as closely as possible, changing ONLY the test-specific part (use each member\'s English source to know what that part is, and keep the test terminology already used in that member or in other locked members). If several members are locked and differ, follow the one that best fits most members. Return locked members unchanged. Gender: fa = women only (feminine), ma = men only (masculine), all other tests and "(base)" = all genders (gender-neutral, never dual forms like (e), /a, (-a), \u0259). Keep placeholders like [%1$s:x], HTML tags and line breaks exactly. Reply with JSON only: {"items":[{"i":<id>,"t":"<string>"}]} for every input item.';
    const groups = {}; for (const b of batch) (groups[b.g] = groups[b.g] || []).push({ i: b.i, test: b.test, key: b.key, en: b.en, t: b.t, lock: b.lock });
    out.push({ json: { iso, n: batch.length, body: { model: 'gpt-4.1', temperature: 0.1, response_format: { type: 'json_object' }, messages: [ { role: 'system', content: sys }, { role: 'user', content: JSON.stringify({ groups: Object.entries(groups).map(([g, items]) => ({ group: g, items })) }) } ] }, src: batch } }); batch = []; };
  for (const [g, items] of Object.entries(fams)) { if (items.length < 3 || !items.some(x => x.lock)) continue; if (batch.length + items.length > 25) flush(); for (const x of items) batch.push(Object.assign({ g }, x)); }
  flush(); }
return out;

const reqs = $('Build batches').all(); const res = $input.all(); const rows = []; const errs = []; const fams = {};
const ph = s => (s.match(/\[%\d\$s:[^\]]+\]|\{\{[^}]+\}\}|<[^>]+>/g) || []).sort().join('|'); const nl = s => (s.match(/\n/g) || []).length;
res.forEach((it, i) => { const r = reqs[i].json; for (const s of r.src) { const k = r.iso + '|' + s.g; fams[k] = fams[k] || []; if (s.lock) fams[k].push(s.t); }
  let parsed = null; try { parsed = JSON.parse(it.json.choices[0].message.content); } catch (e) { errs.push({ iso: r.iso, e: String(e).slice(0,200) }); return; }
  const m = {}; for (const x of (parsed.items||[])) m[String(x.i)] = x.t;
  for (const s of r.src) { if (s.lock) continue; const nt = m[String(s.i)]; if (typeof nt !== 'string') { errs.push({ iso: r.iso, missing: s.i }); continue; }
    const flags = []; if (ph(nt) !== ph(s.t)) flags.push('placeholder/html'); if (nl(nt) !== nl(s.t)) flags.push('linebreaks');
    rows.push({ iso: r.iso, g: s.g, test: s.test, tid: s.i, kid: s.kid, key: s.key, en: s.en, old: s.t, new: nt, flags }); } });
return [{ json: { n: rows.length, errs, fams, rows } }];
